~()?\"']/g, ' ')\n .replace(/\\s+/g,:
~()?"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Uiterst nauwkeurige zoek- en semantische query-engine
 */
exporteer asynchrone functie searchSentences(
  vraag:tekenreeks,
  filters: ZoekFilterOpties = {}
): Belofte<{ resultaten: SentenceItem[]; totaal:aantal; semantischeMatches?: SemanticExplanationMatch[] }> {
  const all = wacht op loadSentences();
  const genormaliseerdeQuery = normalizeText(query);
  const queryTokens = genormaliseerdeQuery? normalizedQuery.split(' ').filter(Boolean) : [];

  const {
    cefr = 'alle',
    sectie = 'alle',
    categorie = 'alle',
    subcategorie = 'alle',
    grammatica = 'alle',
    formaliteit = 'alles',
    limiet = 50,
    verschuiving = 0,
  } = filters;

  // Filterpas
  laat filteren = all.filter(s => {
    if (cefr !== 'all' && s.cefr !== cefr) retourneert false;
    if (sectie !== 'alles' && s.sectie !==sectie) retourneert false;
    if (categorie !== 'alles' && s.categorie !== categorie) retourneert false;
    if (subcategorie !== 'alles' && s.subcategorie !== subcategorie) retourneert false;
    if (grammatica !== 'all' && !s.grammar.toLowerCase().includes(grammatica.toLowerCase())) retourneert false;
    if (formaliteit !== 'alles' && s.formality.toLowerCase() !== formaliteit.toLowerCase()) retourneert false;
    retourneer waar;
  });

  if (!normalizedQuery) {
    const totaal = gefilterd.lengte;
    const gepagineerd = gefilterd. slice(offset, offset + limiet);
    return { resultaten: gepagineerd, totaal };
  }

  // Scoringsalgoritme
  interfaceScoredItem {
    item: ZinItem;
    score:getal;
    aspect: SemanticExplanationMatch['matchedAspect'];
  }

  const gescoord: ScoredItem[] = [];

  voor (const s van gefilterd) {
    laat scoren = 0;
    let matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'english';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.grammatica);
    const normPurpose = normalizeText(s.doel);

    // Exacte volledige zinsovereenkomst
    if (normEn === genormaliseerdeQuery) {
      score += 100;
      matchedAspect = 'Engels';
    } else if (normEg === genormaliseerdeQuery) {
      score += 95;
      matchedAspect = 'arabisch-eg';
    } else if (normFusha === genormaliseerdeQuery) {
      score += 90;
      matchedAspect = 'arabisch-fusha';
    }

    // Subtekenreeks bevat
    if (normEn.includes(genormaliseerdeQuery)) {
      score += 50;
      matchedAspect = 'Engels';
    } else if (normEg.includes(normalizedQuery)) {
      score += 45;
      matchedAspect = 'arabisch-eg';
    } else if (normFusha.includes(normalizedQuery)) {
      score += 40;
      matchedAspect = 'arabisch-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      score += 35;
      matchedAspect = 'grammatica';
    } else if (normPurpose.includes(normalizedQuery)) {
      score += 30;
      matchedAspect = 'concept';
    }

    // Token-overeenkomst
    laat tokenMatches = 0;
    for (const-token van queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    score += tokenMatches;

    als (score > 0) {
      gescoord.push({ item: s, score, aspect: matchedAspect });
    }
  }

  gescoord.sort((a, b) => b.score - a.score);

  // Semantische uitleg komt overeen met topitems
  const semanticMatches: SemanticExplanationMatch[] = gescoord.slice(0, 5).map(s => {
    laat nuance = '';
    if (s.item.grammar.toLowerCase().includes('verleden continu')) {
      nuance = 'De ononderbroken verleden tijd geeft aan dat een gebeurtenis op een specifiek tijdstip in het verleden aan de gang was.';
    } else if (s.item.grammar.toLowerCase().includes('present perfect continu')) {
      nuance = 'De onvoltooid tegenwoordige tijd benadrukt de tijd uit het verleden en loopt door tot het moment van spreken.';
    } else if (s.item.grammar.toLowerCase().includes('toekomstig perfect')) {
      nuance = 'De toekomstige voltooide tijd drukt uit dat een gebeurtenis voltooid zal zijn vóór een specifiek tijdstip in de toekomst.';
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      nuance = 'De vorm van indirect verzoek is het toppunt van diplomatieke etiquette in Engelse communicatie.';
    }
    terug {
      zin: s.item,
      gelijkenisScore: Math.min(100, s.score),
      nuanceExplanationAr: nuance,
      matchedAspect: s.aspect,
    };
  });

  const totaal = gescoord. lengte;
  const gepagineerd = gescoord.slice(offset, offset + limiet).map(s => s.item);

  terug {
    resultaten: gepagineerd,
    totaal,
    semantischematches,
  };
}

/**
 * Deterministische dagelijkse zin (identiek voor alle gebruikers op een bepaalde dag)
 */
exporteer asynchrone functie getDailySentence(): Promise<SentenceItem | nul> {
  const all = wacht op loadSentences();
  if (all. lengte === 0) retourneert null;

  const vandaag = nieuwe datum();
  const dayOfYear = Math.floor(
    (vandaag.getTime() - nieuwe datum(vandaag.getFullYear(), 0, 0).getTime()) / 1000 / 60 / 60 / 24
  );
  const index = Math.abs((dayOfYear * 97 + today.getFullYear()) % all.length);
  retourneer alles[index] || alles[0];
}

/**
 * Deterministische zin van de week
 */
exporteer asynchrone functie getSentenceOfTheWeek(): Promise<SentenceItem | nul> {
  const all = wacht op loadSentences();
  if (all. lengte === 0) retourneert null;

  const vandaag = nieuwe datum();
  const weeknummer = Math.ceil(
    ((vandaag.getTime() - nieuwe datum(vandaag.getFullYear(), 0, 1). getTime()) / 86400000 + 1) / 7
  );
  // Geef de voorkeur aan B2 of C1 voor zin van de week
  const b2c1 = all.filter(s => s.cefr === 'B2' || s.cefr === 'C1');
  const pool = b2c1.length > 0 ? b2c1:alles;
  const index = Math.abs((weekNumber * 31) % pool.lengte);
  retourpool[index] || zwembad[0];
}

/**
 * Krijg willekeurige zin, optioneel CEFR- of sectiefilter
 */
export asynchrone functie getRandomSentence(cefr?: CEFRLevel, sectie?: string): Promise<SentenceItem | nul> {
  const all = wacht op loadSentences();
  laat pool = alles;
  als (cefr) {
    pool = pool.filter(s => s.cefr === cefr);
  }
  als (sectie) {
    zwembad = zwembad. filter(s => s. sectie === sectie);
  }
  if (pool. lengte === 0) retourneert null;
  const randIdx = Math.floor(Math.random() * pool.lengte);
  retourpool[randIdx];
}
